{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.bananaclub_master_data as with shopify_data as ( SELECT reference_code order_name, CASE WHEN LOWER(ARRAY_TO_STRING(payment_gateway, \',\')) LIKE \'%cash%\' THEN \'COD\' WHEN LOWER(ARRAY_TO_STRING(payment_gateway, \',\')) LIKE \'%returnprime%\' THEN \'RetPrime\' WHEN LOWER(ARRAY_TO_STRING(payment_gateway, \',\')) LIKE \'%manual%\' THEN \'Others\' WHEN LOWER(ARRAY_TO_STRING(payment_gateway, \',\')) LIKE \'%custom%\' THEN \'Others\' ELSE \'Prepaid\' END AS payment_type, FORMAT_DATE(\'%b-%y\', order_Date) AS mmmyy, selling_price order_value, QUANTITY, order_id, safe_divide(selling_price, sum(selling_price) over (partition by reference_code)) ratio, sku, ordeR_date, ARRAY_TO_STRING(payment_gateway, \',\') pay, fulfillment_status, TAX, shipping_price, awb, SALES_ORDER_ITEM_ID, exchange_flag FROM maplemonk.bananaclub_sales_consolidated WHERE marketplace = \'WEBSITE\' ), gokwik_transactions as ( select distinct udf1 ordeR_name , gokwik_reference_id , entity_id , amount , fee , tax , settled_amount , method , cast(left(settlement_date,10) as date) settlement_date , utr , payment_provider from maplemonk.banana_club_settlements_recon where type = \'transaction\' and udf1 <> \'NA\' ) , gokwik_refunds as ( select order_name, gokwik_order_id, sum(amount) amount, sum(tax) tax, sum(fee) fee, sum(settled_amount) settled_amount from ( select distinct udf1 ordeR_name , gokwik_reference_id gokwik_ordeR_id , entity_id gokwik_transaction_id , amount amount , fee fee , tax tax , settled_amount settled_amount , method , cast(left(settlement_date,10) as date) settlement_date , utr , payment_provider from maplemonk.banana_club_settlements_recon where type = \'refund\' and udf1 <> \'NA\' ) group by 1,2 ) , snapmint_transactions as ( select distinct ordeR_id gokwik_payment_id, b.udf1 order_name , ordeR_value , gst_amount , total_subvention , settlement_amount , settlement_date from maplemonk.snapmint_get_settlement_data a left join( select distinct udf1, entity_id from maplemonk.banana_club_settlements_recon where type = \'transaction\' and udf1 <> \'NA\' ) b on a.ordeR_id = b.entity_id where ARRAY_LENGTH(refund_data) = 0 ), snapmint_refunds as ( select distinct ordeR_id gokwik_payment_id, b.udf1 order_name , ordeR_value , gst_amount , total_subvention , settlement_amount , settlement_date from maplemonk.snapmint_get_settlement_data a left join( select distinct udf1, entity_id from maplemonk.banana_club_settlements_recon where udf1 <> \'NA\' ) b on a.ordeR_id = b.entity_id where ARRAY_LENGTH(refund_data) > 0 ), shiprocket_data as ( select ID, SPLIT(channel_order_id, \'_\')[OFFSET(0)] channel_order_id, zone, UPPER(status) AS status, REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.awb\') as string), \'\"\', \'\') AS awb, REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.courier\') as string), \'\"\', \'\') AS courier, CAST(JSON_VALUE(awb_data, \'$.charges.freight_charges\') AS string) AS shipping_charges, DATETIME(PARSE_TIMESTAMP(\'%d %b %Y, %I:%M %p\', REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.pickedup_timestamp\') as string), \'\"\', \'\')),\'Asia/Kolkata\') AS pickedup_timestamp, DATETIME(TIMESTAMP(nullif(REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.pickup_scheduled_date\') as string), \'\"\', \'\'), \'0000-00-00 00:00:00\' )), \'Asia/Kolkata\') pickup_scheduled_date, DATETIME(TIMESTAMP(nullif(REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.delivered_date\') as string), \'\"\', \'\'), \'0000-00-00 00:00:00\' )), \'Asia/Kolkata\') delivered_date, REPLACE(cast(JSON_EXTRACT_SCALAR(P, \'$.channel_sku\') as string), \'\"\', \'\') AS channel_sku, coalesce(REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.rto_awb\') as string), \'\"\', \'\'), REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.return_awb\') as string), \'\"\', \'\')) AS Return_awb, DATETIME(TIMESTAMP(nullif(REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.rto_initiated_date\') as string), \'\"\', \'\'), \'0000-00-00 00:00:00\' )), \'Asia/Kolkata\') rto_initiated_date, DATETIME(TIMESTAMP(nullif(REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.rto_delivered_date\') as string), \'\"\', \'\'), \'0000-00-00 00:00:00\' )), \'Asia/Kolkata\') rto_delivered_date FROM `MAPLEMONK.Shiprocket_Shiprocket_orders` left join UNNEST(SHIPMENTS) AS A left join UNNEST(products) AS P Qualify row_number() over(partition by REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.awb\') as string), \'\"\', \'\'), REPLACE(cast(JSON_EXTRACT_SCALAR(P, \'$.channel_sku\') as string), \'\"\', \'\') order by 1) = 1 ), Unicommerce_Sales as ( select Display_Order_Code reference_code ,Item_SKU_Code as SKU ,Facility facility ,Channel_Name ,shipping_Address_state ,invoice_created ,sum(cast(mrp as float64)) mrp ,sum(cast(total_price as float64)) total_price ,Dispatch_Date ,tracking_number from `MAPLEMONK.Bananaclub_DB_get_sale_orders` where invoice_created <> \'\' group by 1,2,3,4,5,6,9,10 ) , Courier_Returns as ( select AWB_No ,SKU_CODE ,datetime(Created) Created ,Putaway_Comment from `MAPLEMONK.Bananaclub_DB_get_courier_returns_itemwise_new` qualify row_number() over(partition by AWB_No,SKU_Code order by length(ifnull(Putaway_Comment,\'\')) desc ) = 1 ), Reverse_PickUp as ( Select Tracking_No ,Item_SkuCode ,datetime(Reverse_Pickup_Created) as Reverse_Pickup_Created ,QC_Comment from `MAPLEMONK.Bananaclub_DB_get_copy_of_reverse_pickup` qualify row_number() over(partition by Tracking_No,Item_SkuCode order by 1) = 1 ), tally_gst as ( Select entity ,Invoice_number ,Original_Sale_No reference_code ,product_sku_code sku from `MAPLEMONK.Bananaclub_DB_get_tally_gst_report` Qualify Row_Number() over(partition by Original_Sale_No,product_sku_code order by 1) = 1 ) , tally_gst_return as ( Select string_agg(date) dates ,sale_ordeR_number reference_code ,product_sku_code sku ,string_agg(distinct Invoice_number) return_invoice_number ,Return_Type ,sum(cast(total as float64)) return_total from `MAPLEMONK.Bananaclub_DB_get_tally_return_gst_report` group by 2,3,5 ) , pragma_data as ( SELECT created_at, order_name, JSON_VALUE(item, \'$.product_sku\') AS sku, JSON_VALUE(item, \'$.customer_reason_label\') AS customer_reason_label, JSON_VALUE(item, \'$.return_type\') AS return_type, JSON_VALUE(item, \'$.quantity\') AS quantity, JSON_VALUE(item, \'$.item_refund_amount\') AS item_refund_amount, customer_preferred_refund_method, JSON_VALUE(item, \'$.exchange_product_sku\') AS exchange_sku, FROM maplemonk.webhook_pragma, UNNEST(JSON_EXTRACT_ARRAY(replace(replace(replace(replace(REPLACE(line_items, \"\'\", \'\"\'),\'None\',\'null\'),\'True\',\'true\'),\'False\',\'false\'), \'\"null\"\', \'null\'))) AS item Qualify row_number() over(partition by order_name, JSON_VALUE(item, \'$.product_sku\') order by ingested_at desc ) = 1 ) select a.* , b.amount*ratio gokwik_transaction_amount , b.fee*ratio gokwik_transaction_fee , b.tax*ratio gokwik_transaction_tax , b.settled_amount*ratio gokwik_transaction_settled_amount , c.amount*ratio gokwik_refund_amount , c.fee*ratio gokwik_refund_fee , c.tax*ratio gokwik_refund_tax , c.settled_amount*ratio gokwik_refund_settled_amount , d.ordeR_value*ratio snapmint_transaction_ordeR_value , d.gst_amount*ratio snapmint_transaction_gst_amount , d.total_subvention*ratio snapmint_transaction_total_subvention , d.settlement_amount*ratio snapmint_transaction_settlement_amount , e.ordeR_value*ratio snapmint_refund_ordeR_value , e.gst_amount*ratio snapmint_refund_gst_amount , e.total_subvention*ratio snapmint_refund_total_subvention , e.settlement_amount*ratio snapmint_refund_settlement_amount , f.status shiprocket_status , f.courier courier_company , f.awb shiprocket_awb , f.pickedup_timestamp order_pickedup_date , case when status like \'%RTO%\' or status like \'%RETURN%\' then status end as return_Status , case when status like \'%RTO%\' or status like \'%RETURN%\' then courier end as return_courier , return_awb , safe_cast(f.shipping_charges as float64)*ratio shipping_charges , us.facility , us.channel_name , us.shipping_address_state , us.invoice_Created , us.mrp , us.total_price , us.dispatch_date , us.tracking_number , tg.entity , tg.invoice_number , tgr.return_type , tgr.dates , tgr.return_invoice_number , tgr.return_total , pd.customer_reason_label , pd.return_type pragma_return_type , pd.quantity pragma_quantity from shopify_data a left join gokwik_transactions b on a.ordeR_name = b.ordeR_name left join gokwik_refunds c on a.ordeR_name = c.ordeR_name left join snapmint_transactions d on a.ordeR_name = d.ordeR_name left join snapmint_transactions e on a.ordeR_name = e.ordeR_name left join shiprocket_data f on a.ordeR_name = f.channel_order_id and a.sku = f.channel_sku left join Unicommerce_Sales us on a.order_name = us.reference_code and a.sku = us.sku left join tally_gst tg on a.order_name = tg.reference_code and a.sku = tg.sku left join tally_gst_return tgr on a.order_name = tgr.reference_code and a.sku = tgr.sku left join pragma_data pd on a.order_name = pd.order_name and a.sku = pd.sku ;",
                    "transaction": true
